custom_css:
/* ===== ВКонтакте 2017 — тема SillyTavern ===== */
/* Порт темы Tavo. Одна тема, две палитры: светлая по умолчанию, тёмная по пометке
   <html data-vk-theme="dark"> — её ставит расширение «ВКонтакте 2017 🌓».
   Цвета — переменные --vk-*, значения лежат в build.py. После правок: python3 build.py.
   В таверне этот CSS лежит в поле «Свой CSS» темы. */

@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap');

:root {
  --vk-in: #2c2d2e;
  --vk-in-line: #1f2021;
  --vk-out: #2b3f57;
  --vk-out-line: #213247;
  --vk-bg: #0f0f10;
  --vk-text: #e1e3e6;
  --vk-tone: #939ca6;
  --vk-hr: rgba(255, 255, 255, 0.12);
  --vk-link: #71aaeb;
  --vk-line-accent: #71aaeb;
  --vk-accent: #4a7bb5;
  --vk-accent-active: #3d6697;
  --vk-surface: #19191a;
  --vk-border: #2c2d2e;
  --vk-placeholder: #76787a;
  --vk-muted: #76787a;
  --vk-check-border: #5d5f61;
  --vk-header: #2d4a6b;
  --vk-float-shadow: rgba(0, 0, 0, 0.5);
  --vk-menu-shadow: rgba(0, 0, 0, 0.6);
  --vk-soft: #232324;
  --vk-hover: #222223;
  --vk-selected: #2a2b2c;
  --vk-line: #2c2d2e;
  --vk-field-border: #3a3b3c;
  --vk-field-focus: #5d5f61;
  --vk-btn: #2c2d2e;
  --vk-btn-hover: #363738;
  --vk-btn-text: #c5d0db;
  --vk-track: #3a3b3c;
  --vk-card-shadow: 0 0 0 1px #2c2d2e;
  --vk-icon: #909499;
}

:root[data-vk-theme="dark"] {
  --vk-in: #2c2d2e;
  --vk-in-line: #1f2021;
  --vk-out: #2b3f57;
  --vk-out-line: #213247;
  --vk-bg: #0f0f10;
  --vk-text: #e1e3e6;
  --vk-tone: #939ca6;
  --vk-hr: rgba(255, 255, 255, 0.12);
  --vk-link: #71aaeb;
  --vk-line-accent: #71aaeb;
  --vk-accent: #4a7bb5;
  --vk-accent-active: #3d6697;
  --vk-surface: #19191a;
  --vk-border: #2c2d2e;
  --vk-placeholder: #76787a;
  --vk-muted: #76787a;
  --vk-check-border: #5d5f61;
  --vk-header: #2d4a6b;
  --vk-float-shadow: rgba(0, 0, 0, 0.5);
  --vk-menu-shadow: rgba(0, 0, 0, 0.6);
  --vk-soft: #232324;
  --vk-hover: #222223;
  --vk-selected: #2a2b2c;
  --vk-line: #2c2d2e;
  --vk-field-border: #3a3b3c;
  --vk-field-focus: #5d5f61;
  --vk-btn: #2c2d2e;
  --vk-btn-hover: #363738;
  --vk-btn-text: #c5d0db;
  --vk-track: #3a3b3c;
  --vk-card-shadow: 0 0 0 1px #2c2d2e;
  --vk-icon: #909499;
}

