#right-nav-panel .group_select {
  flex-wrap: nowrap !important;
  align-items: center !important;
}
#right-nav-panel .character_select .character_select_container,
#right-nav-panel .group_select .group_select_container {
  width: auto !important;
  flex: 1 1 auto;
  min-width: 0;
}
/* замок и кнопка списка — в одну строку, а не столбиком */
#CharListButtonAndHotSwaps > .flexFlowColumn {
  flex-direction: row !important;
  align-items: center;
  gap: 8px;
}
#right-nav-panel #rm_button_panel_pin_div label,
#right-nav-panel #rm_button_panel_pin_div .right_menu_button {
  font-size: 16px !important;
}

/* =====================================================================
   ПОЛЕ ВВОДА, ЭКРАН ПРИВЕТСТВИЯ И СПИСОК ЧАТОВ
   ===================================================================== */

/* таверна центрует подсказку в пустом поле (#send_textarea::placeholder) — у ВК она слева */
#send_textarea:placeholder-shown {
  text-align: left !important;
}
#send_textarea::placeholder {
  text-align: left !important;
  color: var(--vk-placeholder) !important;
  opacity: 1 !important;
}

/* Лого SillyTavern, версия и ссылки (Документация/GitHub/Discord) на стартовом экране.
   Включаются в редакторе темы: Элементы → «Шапка приветствия таверны». */
html:not(.vk-welcome) .welcomePanel .welcomeShortcuts,
html:not(.vk-welcome) .welcomePanel .welcomeShortcutsSeparator {
  display: none !important;
}
/* из шапки таверны прячем лого и версию, но оставляем шестерёнку: в ней задаётся,
   сколько диалогов показывать (по умолчанию таверна показывает всего три) */
html:not(.vk-welcome) .welcomePanel .welcomeHeaderTitle {
  display: flex !important;
  justify-content: flex-end !important;
  align-items: center !important;
  gap: 4px !important;
  margin: 0 !important;
  padding: 8px 12px 0 !important;
  min-height: 0 !important;
  border: none !important;
}
html:not(.vk-welcome) .welcomePanel .welcomeHeaderLogo,
html:not(.vk-welcome) .welcomePanel .welcomeHeaderVersionDisplay,
html:not(.vk-welcome) .welcomePanel .showRecentChats,
html:not(.vk-welcome) .welcomePanel .hideRecentChats {
  display: none !important;
}
html:not(.vk-welcome) .welcomePanel .welcomeHeaderTitle .mes_button {
  width: 28px !important;
  height: 28px !important;
  margin: 0 !important;
  padding: 0 !important;
  display: grid !important;
  place-items: center;
  font-size: 14px !important;
  color: var(--vk-icon) !important;
  opacity: 1 !important;
}
html:not(.vk-welcome) .welcomePanel .welcomeHeaderTitle .mes_button:hover {
  color: var(--vk-accent) !important;
}
.welcomePanel {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.welcomePanel .recentChatsTitle {
  font-size: 15px !important;
  font-weight: 500 !important;
  color: var(--vk-text) !important;
}
/* недавние чаты — строками, как диалоги ВК */
.welcomeRecent .recentChatList .recentChat {
  border: none !important;
  border-bottom: 1px solid var(--vk-line) !important;
  border-radius: 0 !important;
  background: var(--vk-surface) !important;
  padding: 8px 12px !important;
}
.welcomeRecent .recentChatList .recentChat:hover {
  background: var(--vk-hover) !important;
}
.welcomeRecent .recentChatList .recentChat .avatar img {
  border-radius: 50% !important;
}
.welcomeRecent .recentChatList .recentChat .chatName {
  font-weight: 500 !important;
  color: var(--vk-text) !important;
}
.welcomeRecent .recentChatList .recentChat .chatMessage,
.welcomeRecent .recentChatList .recentChat .chatStats {
  color: var(--vk-muted) !important;
}

/* высота поля ввода — ползунок в редакторе темы (без него как у таверны) */
html:root #send_textarea {
  min-height: var(--vk-input-height, calc(var(--bottomFormBlockSize) + 2px)) !important;
}

/* СПИСОК ДИАЛОГОВ НА СТАРТОВОМ ЭКРАНЕ — карточкой, как «Сообщения» ВК.
   Если когда-то нажали «скрыть недавние чаты», таверна прячет список, а кнопка «показать»
   спрятана у нас вместе с шапкой. Поэтому показываем всегда; выключается в редакторе: Элементы. */
html.vk-welcome-chats .welcomePanel.recentHidden .recentChatsTitle,
html.vk-welcome-chats .welcomePanel.recentHidden .welcomeRecent {
  display: block !important;
}
html:not(.vk-welcome-chats) .welcomePanel .recentChatsTitle,
html:not(.vk-welcome-chats) .welcomePanel .welcomeRecent,
html:not(.vk-welcome-chats):not(.vk-welcome) #chat .welcomePanel {
  display: none !important;
}
html.vk-welcome-chats #chat .welcomePanel {
  width: calc(100% - 16px) !important;
  max-width: 440px !important;
  margin: 28px auto 0 !important;
  padding: 0 !important;
  border-radius: 6px !important;
  background: var(--vk-surface) !important;
  box-shadow: var(--vk-card-shadow) !important;
  overflow: hidden;
}
html.vk-welcome-chats #chat .welcomePanel ~ .mes[type="welcome_prompt"] .mes_block {
  margin-top: 12px !important;
}
html.vk-welcome-chats .welcomePanel .welcomeHeader {
  margin: 0 !important;
  padding: 2px 16px 10px !important;
  border-bottom: 1px solid var(--vk-line) !important;
}
html.vk-welcome-chats .welcomePanel .recentChatsTitle {
  font-size: 14px !important;
  text-align: left !important;
}
html.vk-welcome-chats .welcomeRecent,
html.vk-welcome-chats .welcomeRecent .recentChatList {
  margin: 0 !important;
  padding: 0 !important;
  gap: 0 !important;
  max-height: none !important;
}
html.vk-welcome-chats .welcomeRecent .recentChatList .recentChat {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  margin: 0 !important;
  padding: 9px 16px !important;
  background: transparent !important;
  border: none !important;
  border-bottom: 1px solid var(--vk-line) !important;
  border-radius: 0 !important;
  cursor: pointer;
}
html.vk-welcome-chats .welcomeRecent .recentChatList .recentChat.hidden {
  display: none !important;
}
html.vk-welcome-chats .welcomeRecent .recentChatList .recentChat:hover {
  background: var(--vk-hover) !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .avatar {
  flex: none !important;
  width: 50px !important;
  height: 50px !important;
  margin: 0 !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .avatar img {
  width: 50px !important;
  height: 50px !important;
  object-fit: cover !important;
  border-radius: 50% !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .recentChatInfo {
  flex: 1 !important;
  min-width: 0 !important;
  gap: 2px !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatNameContainer {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
}
/* только имя персонажа, без «– имя файла чата» */
html.vk-welcome-chats .welcomeRecent .recentChat .chatName {
  flex: 1 !important;
  min-width: 0 !important;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13.5px !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatName > span {
  display: none !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatDate {
  flex: none;
  margin-left: auto;
  font-size: 12px !important;
  color: var(--vk-muted) !important;
  opacity: 1 !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat:not(:hover) .chatActions {
  display: none !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatActions .menu_button {
  width: 24px !important;
  height: 24px !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 12px !important;
  background: transparent !important;
  color: var(--vk-icon) !important;
  box-shadow: none !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatActions .menu_button.active {
  color: var(--vk-accent) !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatMessageContainer {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatMessage {
  flex: 1 !important;
  min-width: 0 !important;
  display: -webkit-box !important;
  -webkit-line-clamp: 1 !important;
  line-clamp: 1 !important;
  -webkit-box-orient: vertical !important;
  max-height: 1.5em !important;
  overflow: hidden !important;
  white-space: normal !important;
  font-size: 13px !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .chatStats {
  flex: none;
  font-size: 11px !important;
}
html.vk-welcome-chats .welcomeRecent .recentChat .recentChatPinned {
  display: none !important;
}
html.vk-welcome-chats .welcomeRecent .showMoreChats {
  width: 100% !important;
  margin: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  color: var(--vk-link) !important;
  box-shadow: none !important;
}
html.vk-welcome-chats .welcomeRecent .noRecentChat {
  padding: 16px !important;
  color: var(--vk-muted) !important;
}

/* список файлов чата: дата, размер и число сообщений — читаемо, а не бледно */
#select_chat_popup .select_chat_block {
  border: none !important;
  border-bottom: 1px solid var(--vk-line) !important;
  border-radius: 0 !important;
  margin: 0 !important;
  padding: 8px 10px !important;
}
#select_chat_popup .select_chat_block:hover {
  background: var(--vk-hover) !important;
}
#select_chat_popup .select_chat_block[highlight] {
  background: var(--vk-selected) !important;
}
#select_chat_popup .select_chat_block_filename {
  font-size: 13px !important;
  font-weight: 500 !important;
  color: var(--vk-text) !important;
  opacity: 1 !important;
}
#select_chat_popup .select_chat_block_filename_item:not(.select_chat_block_filename) {
  opacity: 1 !important;
  color: var(--vk-muted) !important;
}
#select_chat_popup .select_chat_block_mes {
  color: var(--vk-muted) !important;
}

/* =====================================================================
   ЭКРАН ЗАГРУЗКИ — сплошной фон ВК и синий логотип
   ===================================================================== */
/* Загрузка у таверны — всплывающее окно (.popup) с #loader внутри: белый прямоугольник
   на сером затемнении. Растягиваем окно на весь экран и красим фоном ВК. */
dialog.popup:has(#loader),
.popup:has(#loader) {
  width: 100vw !important;
  height: 100dvh !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  inset: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background: var(--vk-bg) !important;
}
dialog.popup:has(#loader)::backdrop {
  background: var(--vk-bg) !important;
}
/* красный логотип ST → синий ВК (буквы ST остаются белыми) */
#loader .splash-logo {
  filter: hue-rotate(212deg) saturate(0.5) brightness(1.35) !important;
  transition: none !important;
}
#loader.splash-screen,
dialog.popup:has(#loader) {
  transition: none !important;
}
#loader #load-spinner {
  color: var(--vk-accent) !important;
}
#loader .splash-message {
  font-family: var(--vk-font);
  font-size: 15px !important;
  color: var(--vk-muted) !important;
}

/* =====================================================================
   СТАРТОВЫЙ ЭКРАН — как пустой раздел «Сообщения» ВК
   ===================================================================== */
/* сообщение ассистента «Есть соединение с API?..» скрыто (возвращается в редакторе темы) */
html:not(.vk-welcome-assistant) #chat .mes[type="assistant_message"] {
  display: none !important;
}
/* панели других расширений без открытого чата не нужны */
#chat:has(> .welcomePanel) > :not(.welcomePanel):not(.mes) {
  display: none !important;
}
/* кнопки «Соединение с API / Персонажи / Расширения» — карточка по центру */
#chat .mes[type="welcome_prompt"] {
  justify-content: center !important;
}
#chat .mes[type="welcome_prompt"] .mes_block {
  width: 100% !important;
  max-width: 440px !important;
  margin: 28px auto 0 !important;
  padding: 30px 20px 24px !important;
  border-radius: 6px !important;
  background: var(--vk-surface) !important;
  box-shadow: var(--vk-card-shadow) !important;
  align-items: center;
  text-align: center;
}
#chat .mes[type="welcome_prompt"] .ch_name,
#chat .mes[type="welcome_prompt"] .mesAvatarWrapper {
  display: none !important;
}
#chat .mes[type="welcome_prompt"] .mes_block::before {
  content: "";
  display: block;
  width: 64px;
  height: 64px;
  margin: 0 auto 14px;
  background-color: var(--vk-check-border);
  -webkit-mask: var(--vk-i-dialogs) center / contain no-repeat;
  mask: var(--vk-i-dialogs) center / contain no-repeat;
}
#chat .mes[type="welcome_prompt"] .mes_text {
  width: 100%;
  padding: 0 !important;
}
#chat .mes[type="welcome_prompt"] .mes_text::before {
  content: "Выберите диалог\A или начните новый с персонажем";
  display: block;
  white-space: pre-line;
  margin-bottom: 16px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--vk-muted);
}
#chat .mes[type="welcome_prompt"] .mes_text .flex-container {
  flex-direction: column !important;
  align-items: center !important;
  flex-wrap: nowrap !important;
  gap: 10px !important;
}
#chat .mes[type="welcome_prompt"] .mes_text .menu_button {
  width: 260px !important;
  max-width: 100%;
  margin: 0 0 10px !important;
  padding: 9px 14px !important;
  gap: 8px;
  justify-content: center;
  font-size: 13px !important;
  font-style: normal !important;
}
/* главная кнопка — персонажи, синяя */
#chat .mes[type="welcome_prompt"] .mes_text .menu_button:last-of-type {
  margin-bottom: 0 !important;
}
#chat .mes[type="welcome_prompt"] .mes_text .menu_button[data-target="rightNavHolder"] {
  background-color: var(--vk-accent) !important;
  color: #ffffff !important;
}

/* =====================================================================
   ЧИСЛО СООБЩЕНИЙ У ПЕРСОНАЖЕЙ В СПИСКЕ (ставит расширение)
   ===================================================================== */
#right-nav-panel .character_select .vk2017-count {
  margin-left: auto;
  padding-left: 8px;
  flex: none;
  white-space: nowrap;
  font-size: 12px !important;
  font-weight: 400 !important;
  color: var(--vk-muted) !important;
  opacity: 1 !important;
}
#right-nav-panel .character_select.vk2017-has-count .character_version {
  display: none !important;
}
#right-nav-panel .character_select .character_name_block {
  display: flex !important;
  align-items: baseline;
  flex-wrap: nowrap;
  min-width: 0;
}
#right-nav-panel .character_select .character_name_block .ch_name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* у заголовков таверна при наведении выкручивает яркость на 150% — у ВК такого нет */
#user-settings-block h4,
.standoutHeader.inline-drawer-header:hover,
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
  filter: none !important;
}
#user-settings-block h4 {
  font-size: 14px !important;
  font-weight: 500 !important;
  padding: 6px 10px !important;
}

/* =====================================================================
   ПОЛОСА CHAT TOP BAR И ОЖИДАНИЕ ОТВЕТА
   ===================================================================== */
/* Полоса расширения «Chat Top Bar» (выбор чата, поиск, кнопки) — у ВК её нет,
   шапка диалога уже показывает имя. Возвращается в редакторе темы: Элементы. */
html:not(.vk-topbar) #extensionTopBar,
html:not(.vk-topbar) #extensionConnectionProfiles {
  display: none !important;
}

/* Пока ответ не пришёл, таверна пишет в пузырь «...» — рисуем прыгающие точки ВК */
#chat .mes .mes_text.vk2017-waiting {
  font-size: 0 !important;
  min-height: 20px;
  display: flex !important;
  align-items: center;
}
#chat .mes .mes_text.vk2017-waiting > * {
  display: none !important;
}
#chat .mes .mes_text.vk2017-waiting::after {
  content: "";
  display: block;
  width: 30px;
  height: 14px;
  background-image:
    radial-gradient(circle at center, var(--vk-accent) 3px, transparent 3.6px),
    radial-gradient(circle at center, var(--vk-accent) 3px, transparent 3.6px),
    radial-gradient(circle at center, var(--vk-accent) 3px, transparent 3.6px);
  background-size: 8px 8px;
  background-repeat: no-repeat;
  background-position: 0 6px, 11px 6px, 22px 6px;
  animation: vk2017-wave 1.2s ease-in-out infinite;
}
@keyframes vk2017-wave {
  0%, 100% { background-position: 0 6px, 11px 6px, 22px 6px; opacity: 0.6; }
  20% { background-position: 0 1px, 11px 6px, 22px 6px; opacity: 1; }
  40% { background-position: 0 6px, 11px 1px, 22px 6px; }
  60% { background-position: 0 6px, 11px 6px, 22px 1px; }
}


